    {
      "service": "ts-travel-service",
      "fault_kind": "application_exception",
      "evidence": [
        {"kind": "log", "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE level='SEVERE' AND service_name='ts-travel-service' GROUP BY 1,2", "claim": "ts-travel-service logged 2,528 SEVERE dispatcher exceptions (IllegalArgumentException: Invalid argument) in the incident window, versus none in the normal period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name LIKE 'GET /api/v1/travelservice/routes/%' GROUP BY 1,2,3", "claim": "ts-travel-service GET /routes/{tripId} server spans return 500 Error about 2,528 times, each only about 5 ms of its own time."},
        {"kind": "trace", "sql": "WITH c AS (SELECT 'abn' p, trace_id, span_id, service_name caller, duration::DOUBLE cd FROM abnormal_traces WHERE attr_span_kind='Client' UNION ALL SELECT 'norm', trace_id, span_id, service_name, duration::DOUBLE FROM normal_traces WHERE attr_span_kind='Client'), s AS (SELECT 'abn' p, trace_id, parent_span_id, service_name callee, duration::DOUBLE sd, attr_status_code ss FROM abnormal_traces WHERE attr_span_kind='Server' UNION ALL SELECT 'norm', trace_id, parent_span_id, service_name, duration::DOUBLE, attr_status_code FROM normal_traces WHERE attr_span_kind='Server') SELECT c.p, caller, callee, count(*) n, round(quantile_cont(cd/1e6,0.5),1) client_med_ms, round(quantile_cont(sd/1e6,0.5),1) server_med_ms, round(sum(CASE WHEN ss='Error' THEN 1 ELSE 0 END)*1.0/count(*),2) callee_err_share FROM c JOIN s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id AND s.p=c.p WHERE (caller,callee) IN (('ts-food-service','ts-travel-service'),('ts-route-plan-service','ts-travel-service')) GROUP BY 1,2,3 ORDER BY 2,3,1", "claim": "Calls from food and route-plan to travel-service fail with 500 (error share about 0.93 to 1.0) and their median time rises from about 15–29 ms to about 3.6 s."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel-service", "to": "ts-food-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, round(quantile_cont(c.duration/1e6,0.5),1) client_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-food-service' AND c.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY 1,2,3", "claim": "Food-service's client GET calls to travel-service return errors after about 3.7 s median, and food's own server spans fail as well."}]},
    {"from": "ts-food-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-food-service' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "Food-service's GET /foods server spans show 73 errors with p95 near 6 s, and ui-dashboard food calls rise to about 5.7 s p95."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, c.span_name, c.attr_status_code, count(*) n, round(quantile_cont(c.duration/1e6,0.5),1) client_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY 1,2,3", "claim": "Route-plan's GET calls to travel-service return 500 after about 3.6 s median, with 84 route-plan server-side errors."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service",
     "evidence": [{"kind": "trace", "sql": "WITH c AS (SELECT 'abn' p, trace_id, span_id, service_name caller, duration::DOUBLE cd FROM abnormal_traces WHERE attr_span_kind='Client' UNION ALL SELECT 'norm', trace_id, span_id, service_name, duration::DOUBLE FROM normal_traces WHERE attr_span_kind='Client'), s AS (SELECT 'abn' p, trace_id, parent_span_id, service_name callee, duration::DOUBLE sd, attr_status_code ss FROM abnormal_traces WHERE attr_span_kind='Server' UNION ALL SELECT 'norm', trace_id, parent_span_id, service_name, duration::DOUBLE, attr_status_code FROM normal_traces WHERE attr_span_kind='Server') SELECT c.p, caller, callee, count(*) n, round(quantile_cont(cd/1e6,0.5),1) client_med_ms, round(quantile_cont(sd/1e6,0.5),1) server_med_ms, round(sum(CASE WHEN ss='Error' THEN 1 ELSE 0 END)*1.0/count(*),2) callee_err_share FROM c JOIN s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id AND s.p=c.p WHERE (caller,callee) IN (('ts-travel-plan-service','ts-route-plan-service')) GROUP BY 1,2,3 ORDER BY 1", "claim": "Travel-plan's calls to route-plan rise from about 0.3 s to 60 s median, with 81% of route-plan callees returning errors."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-ui-dashboard') AND attr_span_kind='Server' AND span_name LIKE '%travel%' GROUP BY 1,2", "claim": "Travel-plan server spans and ui-dashboard's travel-plan requests reach p95 latencies of tens of seconds in the incident window."}]}
  ]
}
